-- Generated from Kaggle MyAnimeList dataset for JETRO-PS-02
delete from regional_demand;
delete from titles;

select t.id, r, 
       case 
         when r = 'North' then least(100, (40 + random()*55)::int)
         when r = 'South' then least(100, (35 + random()*55)::int)
         when r = 'West' then least(100, (40 + random()*50)::int)
         when r = 'East' then least(100, (30 + random()*50)::int)
         else least(100, (35 + random()*60)::int)
       end,
       least(100, (30 + random()*65)::int)
from titles t cross join unnest(array['North','South','West','East','North-East']) r
on conflict do nothing;
